cat > /tmp/fanin.py <<'EOF'
import re, os, subprocess, collections

files = subprocess.run(["git","ls-files","*.go"],capture_output=True,text=True).stdout.split()
src = {f: open(f).read() for f in files}

# collect declarations under internal/
decls = []  # (name, path, is_method, pkgdir)
declre = re.compile(r'^func\s+(?:\(([^)]*)\)\s*)?([A-Za-z_]\w*)\s*[\(\[]', re.M)
for f in files:
    if not f.startswith("internal/") or f.endswith("_test.go"): continue
    for m in declre.finditer(src[f]):
        recv, name = m.group(1), m.group(2)
        decls.append((name, f, bool(recv), os.path.dirname(f)))

# count call sites
counts = collections.defaultdict(lambda: collections.Counter())
callre = {}
for name,f,ismeth,pkgdir in decls:
    if name not in callre:
        callre[name] = re.compile(r'(?<![\w.])(\w+\s*\.\s*)?'+re.escape(name)+r'\s*\(')

results = []
for name,f,ismeth,pkgdir in decls:
    if name in ("init","New"): pass
    total = 0
    per = collections.Counter()
    pat = re.compile(r'(?<![\w])(?:(\w+)\s*\.\s*)?'+re.escape(name)+r'\s*\(')
    for g in files:
        if g.endswith("_test.go"): continue
        txt = src[g]
        for mm in pat.finditer(txt):
            # skip the declaration itself
            line_start = txt.rfind("\n",0,mm.start())+1
            line = txt[line_start: txt.find("\n",mm.start())]
            if line.startswith("func "): continue
            qual = mm.group(1)
            if ismeth:
                if qual is None: continue
            else:
                if qual is None:
                    if os.path.dirname(g) != pkgdir: continue
                else:
                    # package-qualified: qual should be a package alias; require same base name-ish
                    if qual != os.path.basename(pkgdir):
                        # could be aliased import; check import in file
                        if not re.search(r'\b'+re.escape(qual)+r'\s+"'+ 'github.com/usememos/memos/'+re.escape(pkgdir)+r'"', txt):
                            continue
            total += 1
            per[g]+=1
    results.append((total, name, f, ismeth, per))

results.sort(reverse=True, key=lambda x:x[0])
for t,name,f,ismeth,per in results[:30]:
    print(t, name, f, "method" if ismeth else "func")
    print("   ", dict(per.most_common(6)))
EOF
python3 /tmp/fanin.py

cat > /tmp/fanin.js <<'EOF'
const {execSync} = require('child_process');
const fs = require('fs'), path = require('path');
const files = execSync('git ls-files "*.go"',{cwd:'/bench/repo'}).toString().trim().split('\n');
const src = {};
for (const f of files) src[f] = fs.readFileSync('/bench/repo/'+f,'utf8');

const declre = /^func\s+(?:\(([^)]*)\)\s*)?([A-Za-z_]\w*)\s*[\(\[]/gm;
const decls = [];
for (const f of files){
  if(!f.startsWith('internal/')||f.endsWith('_test.go')) continue;
  let m; declre.lastIndex=0;
  while((m=declre.exec(src[f]))) decls.push({name:m[2], file:f, isMeth:!!m[1], pkgdir:path.dirname(f), recv:m[1]||''});
}
const esc = s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const results=[];
for(const d of decls){
  const pat = new RegExp('(?<![\\w])(?:(\\w+)\\s*\\.\\s*)?'+esc(d.name)+'\\s*\\(','g');
  let total=0; const per={};
  for(const g of files){
    if(g.endsWith('_test.go')) continue;
    const txt=src[g]; pat.lastIndex=0; let mm;
    while((mm=pat.exec(txt))){
      const ls=txt.lastIndexOf('\n',mm.index)+1;
      const le=txt.indexOf('\n',mm.index);
      const line=txt.slice(ls, le<0?txt.length:le);
      if(/^func\s/.test(line)) continue;
      const qual=mm[1];
      if(d.isMeth){ if(qual===undefined) continue; }
      else {
        if(qual===undefined){ if(path.dirname(g)!==d.pkgdir) continue; }
        else {
          if(qual!==path.basename(d.pkgdir)){
            const im=new RegExp('\\b'+esc(qual)+'\\s+"github.com/usememos/memos/'+esc(d.pkgdir)+'"');
            if(!im.test(txt)) continue;
          }
        }
      }
      total++; per[g]=(per[g]||0)+1;
    }
  }
  results.push({total,...d,per});
}
results.sort((a,b)=>b.total-a.total);
for(const r of results.slice(0,35)){
  console.log(r.total, r.name, r.file, r.isMeth?('method '+r.recv):'func');
}
fs.writeFileSync('/tmp/fanin.json', JSON.stringify(results.slice(0,60),null,1));
EOF
node /tmp/fanin.js

node -e '
const fs=require("fs");const r=JSON.parse(fs.readFileSync("/tmp/fanin.json","utf8"));
for(const x of r.slice(0,60)) console.log(x.total, x.name, x.file, x.isMeth?"M":"F", JSON.stringify(x.per));
' | head -60

